// The Atlas's "Data health" panel (shown next to "Advanced view" once that is on): what the generated data of the selected version
// covers and what it leaves out. Opened by atlas-app.js with import(); reads js/atlas/data/health.js (GENERATED by
// toolbox/atlas/audit_glows.py: glows per version, signs / waypoints, the picture pool) and, from what the page already has, the files
// the version carries of its own (window.AtlasVersionData) and the maps no door leads to (window.ArcanumMaps).

const ID = 'healthPanel';
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const KIND = { n: 'people', c: 'containers', i: 'items on the floor', s: 'signs', w: 'waypoints' };
const fmt = n => Number(n).toLocaleString('en');

function loadHealth() {
  if (window.ArcanumHealth) return Promise.resolve(window.ArcanumHealth);
  return new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = new URL('js/atlas/data/health.js', location.href).href;
    s.onload = () => window.ArcanumHealth ? resolve(window.ArcanumHealth) : reject(new Error('health.js has no data'));
    s.onerror = () => reject(new Error('health.js could not be loaded (run toolbox/atlas/audit_glows.py)'));
    document.head.appendChild(s);
  });
}

function versionKey() { return window.AtlasVer && window.AtlasVer !== 'base' ? window.AtlasVer : 'base'; }

function bar(have, should) {
  const pct = should ? have / should * 100 : 100;
  return `<div class="hl-bar" role="img" aria-label="${pct.toFixed(1)} percent covered"><i style="width:${pct.toFixed(2)}%"></i></div>`;
}

function reasonRows(rows, limit = 12) {
  if (!rows || !rows.length) return '<p class="hl-none">Nothing is missing.</p>';
  const shown = rows.slice(0, limit);
  return `<table class="hl-table"><thead><tr><th>Map</th><th>What</th><th>Why</th><th class="n">Count</th></tr></thead><tbody>${shown.map(([map, kind, why, n]) =>
    `<tr><td>${esc(map)}</td><td>${esc(KIND[kind] || kind)}</td><td>${esc(why)}</td><td class="n">${fmt(n)}</td></tr>`).join('')}</tbody></table>`
    + (rows.length > limit ? `<p class="hl-more">${rows.length - limit} more kinds of gap in the full audit (toolbox/atlas/reports/glow-audit.md).</p>` : '');
}

function build(h) {
  const key = versionKey();
  const names = (window.AtlasData && window.AtlasData.names) || {};
  const label = key === 'base' ? 'Base game + modules' : (names[key] || key);
  const g = h.glows[key];
  const own = (window.AtlasVersionData || {})[key];
  const maps = window.ArcanumMaps;
  const lost = maps ? maps.sections.filter(s => s.group === 'Unreachable maps').map(s => s.name) : [];
  const parts = [];

  parts.push(`<section><h3>Layers</h3>${key === 'base'
    ? '<p>The base game: every file of <code>data/</code>, with its modules.</p>'
    : `<p>${esc(label)} is the base game with its own layer laid over it. The generated files it carries of its own: ${own && own.length ? own.map(n => `<code>${esc(n)}</code>`).join(' ') : 'none (all of the base game\'s)'}; everything else is the base game's.</p>`}</section>`);

  if (g) {
    parts.push(`<section><h3>Glows <small>${esc(g.label)}</small></h3>
      <p><b>${fmt(g.have)}</b> of <b>${fmt(g.should)}</b> people, containers and floor items that should glow on the map do (${g.should ? (g.have / g.should * 100).toFixed(1) : '100'} %); ${fmt(g.should - g.have)} do not, from ${fmt(g.files)} .mob files.</p>
      ${bar(g.have, g.should)}${reasonRows(g.reasons)}
      ${g.extra ? `<p class="hl-more">${fmt(g.extra)} glows of this version's set have no .mob of its own folders (module copies and base-game files the mod re-uses).</p>` : ''}</section>`);
  } else {
    parts.push(`<section><h3>Glows</h3><p class="hl-none">This version has no glow audit yet.</p></section>`);
  }

  if (key === 'base' && h.signs) {
    parts.push(`<section><h3>Signs and waypoints without a glow <small>${fmt(h.signs.count)}</small></h3>${reasonRows(h.signs.reasons, 8)}</section>`);
  }

  parts.push(`<section><h3>Maps no door leads to</h3>${lost.length
    ? `<p>${lost.map(esc).join(', ')}. They are listed under "Unreachable maps".</p>` : '<p class="hl-none">None in this version.</p>'}</section>`);

  const p = h.pool;
  if (p) {
    parts.push(`<section><h3>Glow picture pool</h3><p>${fmt(p.files)} files, ${fmt(p.used)} used by some glow set. Used but missing: <b class="${p.missing ? 'hl-bad' : ''}">${fmt(p.missing)}</b>; unused (orphans): ${fmt(p.orphans)}.</p></section>`);
  }
  parts.push(`<p class="hl-foot">Audit of ${esc(h.generated)}; ${fmt(h.unexplained)} gap${h.unexplained === 1 ? '' : 's'} without an explanation.</p>`);
  return `<div class="hl-card" role="dialog" aria-modal="true" aria-label="Data health"><header><h2>Data health <small>${esc(label)}</small></h2><button type="button" class="hl-close" aria-label="Close">&times;</button></header><div class="hl-body">${parts.join('')}</div></div>`;
}

export function closeHealth() { document.getElementById(ID)?.remove(); }

export async function toggleHealth() {
  if (document.getElementById(ID)) return closeHealth();
  const box = document.createElement('div');
  box.id = ID; box.className = 'hl-overlay';
  box.innerHTML = '<div class="hl-card"><div class="hl-body"><p>Loading…</p></div></div>';
  document.body.appendChild(box);
  const close = e => { if (e.target === box || e.target.closest('.hl-close')) closeHealth(); };
  box.addEventListener('click', close);
  const onKey = e => { if (e.key === 'Escape') { closeHealth(); document.removeEventListener('keydown', onKey); } };
  document.addEventListener('keydown', onKey);
  try { box.innerHTML = build(await loadHealth()); }
  catch (err) { box.querySelector('.hl-body').innerHTML = `<p class="hl-bad">${esc(err.message)}</p>`; }
}
